void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord / iResolution.xy;

    // 使用step函数创建区域效果
    float topRight = step(0.5, uv.x) * (1.0 - step(0.5, uv.y));
    float bottomLeft = (1.0 - step(0.5, uv.x)) * step(0.5, uv.y);
    float bottomRight = step(0.5, uv.x) * step(0.5, uv.y);

    // 根据区域计算颜色
    vec3 color = vec3(topRight + bottomLeft);  // 白色用1.0表示
    color = mix(color, vec3(0.0), bottomRight); // 黑色区域

    // 设置输出颜色
    fragColor = vec4(color, 1.0);
}
